const $ = s => document.querySelector(s);
const today = () => {const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const KEY='bloom-journal-v1';
let state=BloomVault.blank();
let date=today(),page='overview',timer;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const day=()=>state.days[date]||{meals:[],water:0,activities:[],weight:null};
const writableDay=()=>state.days[date]??=( {meals:[],water:0,activities:[],weight:null});
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
async function save(){return saveAccount();}
const total=(field)=>Math.round(day().meals.reduce((n,m)=>n+Number(m[field]||0),0)*10)/10;
const minutes=()=>day().activities.reduce((n,a)=>n+a.minutes,0);
const percent=(a,b)=>Math.max(0,Math.min(100,Math.round(a/b*100)));
const bar=(a,b,color='')=>`<div class="bar"><span style="width:${percent(a,b)}%;${color?'background:'+color:''}"></span></div>`;
const btn=(text,action,cls='primary')=>`<button class="${cls}" data-action="${action}">${text}</button>`;
// Bloom's UI uses the stat hierarchy and rounded chart bars from 21st's
// Health Stat Card, adapted to the existing vanilla JS journal.
function mealList(meals=day().meals){
  if(!meals.length)return `<div class="empty"><span class="empty-symbol">${uiIcon('bowl',30)}</span><strong>A little nourishment starts here.</strong><p>Add a meal and make this space yours.</p><button class="text-button" data-action="meal">Log your first meal ${uiIcon('arrow',15)}</button></div>`;
  return meals.map(m=>`<div class="meal"><span class="food-icon ${m.meal.toLowerCase()}">${uiIcon(({Breakfast:'sun',Lunch:'bowl',Dinner:'moon',Snack:'leaf'})[m.meal])}</span><div class="meal-info"><strong>${esc(m.name)}</strong><p>${esc(m.meal)} <span>·</span> ${m.protein}g protein <span>·</span> ${m.carbs}g carbs <span>·</span> ${m.fat}g fat</p></div><div class="meal-kcal"><strong>${m.calories}</strong> <small>kcal</small>${m.items?`<button class="text-button meal-details-button" data-meal-details="${esc(m.id)}">View items</button>`:''}</div><button class="remove" data-remove-meal="${esc(m.id)}" aria-label="Remove ${esc(m.name)}">${uiIcon('close',14)}</button></div>`).join('');
}
function nutrition(){
  return `<section class="card macro-card"><div class="card-heading"><div><span class="card-kicker">THE BUILDING BLOCKS</span><h2>Macro balance</h2></div><span class="card-icon">${uiIcon('protein')}</span></div>${[['Protein','protein','var(--lime-deep)'],['Carbs','carbs','var(--peach)'],['Fat','fat','var(--lavender)']].map(([title,key,color])=>`<div class="macro"><div class="macro-label"><span><i style="background:${color}"></i>${title}</span><strong>${total(key)}<small> / ${state.goals[key]} g</small></strong></div>${bar(total(key),state.goals[key],color)}</div>`).join('')}<p class="card-footnote">Based on the meals you log.</p></section>`;
}
function water(){
  return `<section class="card water-card"><div class="card-heading"><div><span class="card-kicker">A MOMENT TO REFRESH</span><h2>Stay hydrated</h2></div><span class="card-icon">${uiIcon('water')}</span></div><div class="water-total">${(day().water/1000).toFixed(2)} <small>/ ${(state.goals.water/1000).toFixed(2)} L</small></div><div class="water-glasses" aria-label="${day().water} milliliters consumed">${Array.from({length:8},(_,i)=>`<span class="glass ${day().water/state.goals.water*8>=i+1?'filled':''}"></span>`).join('')}</div><div class="water-controls"><small>${percent(day().water,state.goals.water)}% of your goal</small><div><button class="water-minus" data-action="water-minus" aria-label="Remove 250 ml">−</button><button data-action="water-plus">${uiIcon('plus',14)} 250 ml</button></div></div></section>`;
}
function stats(){
  const c=total('calories'),g=state.goals;
  return `<div class="stats"><section class="card stat-card calorie-card"><div class="stat-head"><span>${uiIcon('fire',18)} Calorie intake</span><span class="stat-tag">TODAY</span></div><div class="calorie-body"><div><div class="stat-number">${c.toLocaleString()}<small> kcal</small></div><p class="stat-note">of ${g.calories.toLocaleString()} kcal goal</p></div><div class="ring" style="--value:${percent(c,g.calories)}"><div>${percent(c,g.calories)}<small>%</small></div></div></div><div class="stat-bottom"><span>${Math.max(0,g.calories-c).toLocaleString()} kcal remaining</span>${uiIcon('arrowUp',14)}</div></section><section class="card stat-card"><div class="stat-head"><span>${uiIcon('water',18)} Hydration</span><span class="stat-dot blue"></span></div><div class="stat-number">${(day().water/1000).toFixed(2)}<small> L</small></div>${bar(day().water,g.water,'var(--blue)')}<div class="stat-bottom"><span>Daily goal ${(g.water/1000).toFixed(1)} L</span><strong>${percent(day().water,g.water)}%</strong></div></section><section class="card stat-card"><div class="stat-head"><span>${uiIcon('activity',18)} Movement</span><span class="stat-dot purple"></span></div><div class="stat-number">${minutes()}<small> min</small></div>${bar(minutes(),g.activity,'var(--lavender)')}<div class="stat-bottom"><span>Daily goal ${g.activity} min</span><strong>${percent(minutes(),g.activity)}%</strong></div></section><section class="card stat-card"><div class="stat-head"><span>${uiIcon('protein',18)} Protein</span><span class="stat-dot lime"></span></div><div class="stat-number">${total('protein')}<small> g</small></div>${bar(total('protein'),g.protein,'var(--lime-deep)')}<div class="stat-bottom"><span>Daily goal ${g.protein} g</span><strong>${percent(total('protein'),g.protein)}%</strong></div></section></div>`;
}
function overview(){
  return `${stats()}<div class="overview-feature"><section class="hero"><div class="hero-copy"><span class="pill">A LITTLE BETTER, EVERY DAY</span><h2>Good habits.<br><em>Your kind of pace.</em></h2><p>No perfect days needed. Just a little care,<br>one meal and one small step at a time.</p><a class="hero-photo-link" href="#scan">Meet your next meal ${uiIcon('arrowUp',16)}</a></div><div class="hero-art" aria-hidden="true"><span class="hero-orbit"></span><img src="assets/bloom-active-friends-cutout.png" alt="" width="1536" height="1024"></div></section><section class="card quick-card"><span class="card-kicker">MAKE A LITTLE PROGRESS</span><h2>What’s next?</h2><button data-action="meal"><span class="quick-icon lime-bg">${uiIcon('food')}</span><span><strong>Log a meal</strong><small>A little fuel for your day</small></span>${uiIcon('plus',17)}</button><a href="#scan"><span class="quick-icon peach-bg">${uiIcon('camera')}</span><span><strong>Snap your plate</strong><small>Photo, review, and enjoy</small></span>${uiIcon('arrowUp',17)}</a><button data-action="activity"><span class="quick-icon lavender-bg">${uiIcon('activity')}</span><span><strong>Move your way</strong><small>Every active minute counts</small></span>${uiIcon('plus',17)}</button></section></div><div class="grid"><section class="card journal-card"><div class="card-heading"><div><span class="card-kicker">YOUR DAILY FUEL</span><h2>On your plate</h2></div><button class="secondary small-button" data-action="meal">${uiIcon('plus',15)} Add food</button></div>${mealList()}<a class="card-link" href="#food">Open food journal ${uiIcon('arrow',16)}</a></section><div class="right-stack">${water()}${nutrition()}</div></div>`;
}
function food(){
  const groups=['Breakfast','Lunch','Dinner','Snack'].filter(type=>day().meals.some(m=>m.meal===type));
  return `<div class="page-toolbar"><span class="summary-text"><strong>${day().meals.length}</strong> meals logged <span>·</span> <strong>${total('calories').toLocaleString()}</strong> kcal today</span><div class="toolbar-actions"><a class="secondary" href="#scan">${uiIcon('camera',17)} Photo meal</a><button class="primary" data-action="meal">${uiIcon('plus',17)} Add food</button></div></div><div class="grid"><div class="meal-groups">${groups.length?groups.map(type=>{const meals=day().meals.filter(m=>m.meal===type);return `<section class="card journal-card"><div class="card-heading"><div class="meal-group-title"><span class="group-icon">${uiIcon(({Breakfast:'sun',Lunch:'bowl',Dinner:'moon',Snack:'leaf'})[type])}</span><h2>${type}</h2></div><span class="section-count">${Math.round(meals.reduce((n,m)=>n+m.calories,0)*10)/10} kcal</span></div>${mealList(meals)}</section>`;}).join(''):`<section class="card journal-card">${mealList()}</section>`}<section class="soft-note">${uiIcon('info',20)}<div><strong>Your plate is personal.</strong><p>Use food labels or recipes for a closer estimate. You can always remove an entry and add a corrected one.</p></div></section></div><div class="right-stack">${nutrition()}${dailyNutrients()}</div></div>`;
}
function activity(){
  return `${stats()}<div class="grid"><section class="card"><div class="card-heading"><div><span class="card-kicker">MAKE ROOM TO MOVE</span><h2>Your movement journal</h2></div><button class="primary small-button" data-action="activity">${uiIcon('plus',15)} Log activity</button></div>${day().activities.length?day().activities.map(a=>`<div class="activity-row"><span class="activity-icon">${uiIcon('activity',22)}</span><div><strong>${esc(a.type)}</strong><p>${esc(a.note||'A little time for yourself')}</p></div><strong class="activity-duration">${a.minutes}<small> min</small></strong><button class="remove" data-remove-activity="${esc(a.id)}" aria-label="Remove ${esc(a.type)}">${uiIcon('close',14)}</button></div>`).join(''):`<div class="empty"><span class="empty-symbol">${uiIcon('activity',32)}</span><strong>Find your kind of movement.</strong><p>A walk, a stretch, a workout. It all starts somewhere.</p><button class="text-button" data-action="activity">Log your first activity ${uiIcon('arrow',15)}</button></div>`}</section>${water()}</div>${consumedFeed()}`;
}
function progress(){
  const dates=Array.from({length:7},(_,i)=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()-6+i);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;});
  const vals=dates.map(d=>(state.days[d]?.meals||[]).reduce((n,m)=>n+m.calories,0)),max=Math.max(state.goals.calories,...vals),logged=dates.filter(d=>state.days[d]?.meals.length),weekMinutes=dates.reduce((n,d)=>n+(state.days[d]?.activities||[]).reduce((a,b)=>a+b.minutes,0),0),weights=Object.entries(state.days).filter(([,v])=>v.weight!=null).sort(([a],[b])=>b.localeCompare(a));
  return `<div class="progress-highlights"><div>${uiIcon('calendar',22)}<span><small>Days with meals logged</small><strong>${logged.length}<em> / 7 days</em></strong></span></div><div>${uiIcon('activity',22)}<span><small>Movement this week</small><strong>${weekMinutes}<em> min</em></strong></span></div><div>${uiIcon('fire',22)}<span><small>Average on logged days</small><strong>${logged.length?Math.round(vals.reduce((n,v)=>n+v,0)/logged.length).toLocaleString():'—'}<em> kcal</em></strong></span></div></div><div class="grid"><section class="card chart-card"><div class="card-heading"><div><span class="card-kicker">THE BIGGER PICTURE</span><h2>Your week, at a glance</h2><small>Calories logged in the seven days ending ${esc(date)}</small></div><span class="legend-dot">Intake</span></div><div class="chart">${dates.map((d,i)=>`<div class="chart-col ${d===date?'today':''}"><small>${Math.round(vals[i])}</small><div class="chart-bar" style="height:${Math.max(2,vals[i]/max*155)}px" title="${d}: ${vals[i]} kcal"></div><span>${new Date(d+'T12:00:00').toLocaleDateString('en-US',{weekday:'short'})}</span></div>`).join('')}</div><p class="notice">Empty days mean no meals were recorded. A journal is a record of your entries, not a complete picture of your health.</p></section><section class="card weight-card"><div class="card-heading"><div><span class="card-kicker">AT YOUR OWN PACE</span><h2>Weight journal</h2></div><button class="text-button" data-action="weight">${uiIcon('plus',15)} Log weight</button></div>${weights.length?`<div class="weight-latest">${weights[0][1].weight}<small> kg</small><span>Latest entry · ${esc(weights[0][0])}</span></div><div class="weight-history">${weights.slice(0,8).map(([d,v])=>`<div><small>${esc(d)}</small><span>${v.weight} kg <button class="remove" data-remove-weight="${d}" aria-label="Remove weight from ${d}">${uiIcon('close',13)}</button></span></div>`).join('')}</div>`:`<div class="empty"><span class="empty-symbol">${uiIcon('chart',30)}</span><strong>Your own pace.</strong><p>Weight tracking is optional.<br>Add an entry whenever you choose.</p></div>`}</section></div>`;
}
function goals(){
  return `<div class="page-toolbar"><p class="summary-text">A routine that fits <strong>your life.</strong></p><button class="primary" data-action="settings">${uiIcon('settings',17)} Edit goals</button></div><div class="goal-grid">${[['Daily calories','fire',state.goals.calories,'kcal'],['Hydration','water',state.goals.water,'ml'],['Movement','activity',state.goals.activity,'min'],['Protein','protein',state.goals.protein,'g'],['Carbohydrates','bowl',state.goals.carbs,'g'],['Fat','leaf',state.goals.fat,'g']].map(([name,icon,v,unit])=>`<section class="card goal-card"><span class="goal-icon">${uiIcon(icon,23)}</span><h3>${name}</h3><div class="value">${v.toLocaleString()}<small> ${unit}</small></div><p>Daily target</p></section>`).join('')}</div><section class="soft-note">${uiIcon('info',20)}<div><strong>Start with what works for you.</strong><p>Initial targets are examples, not personalized recommendations. Set targets with a qualified professional if you need nutrition guidance.</p></div></section><section class="card data-card"><div><span class="card-kicker">ALWAYS IN YOUR HANDS</span><h2>Your journal belongs to you</h2><p class="notice">${session.guest?'Your guest journal is saved in this browser without a password.':'Your journal is encrypted in your local account.'} Back up your progress before clearing browser data or moving devices.</p></div><div class="data-actions"><button class="secondary" data-action="export">${uiIcon('backup',17)} ${session.guest?'Download guest backup':'Download encrypted backup'}</button><button class="danger" data-action="clear">Clear journal</button></div></section>`;
}
function consumedFeed(){return `<section class="card consumed-card"><div class="card-heading"><div><span class="card-kicker">THE OTHER SIDE OF ENERGY</span><h2>Meals consumed</h2><small>Food intake is tracked separately from your movement.</small></div><a class="text-button" href="#food">Food journal ${uiIcon('arrow',15)}</a></div>${mealList()}</section>`;}
const titles={overview:['Your day, in balance.','Good food. A little movement. Room to be you.'],food:['Good food. Good energy.','A little nourishment, one meal at a time.'],activity:['Move at your own pace.','Your daily dose of feeling a little better.'],progress:['A little progress adds up.','Look at the habits you’re building, one day at a time.'],goals:['Your goals. Your rhythm.','Small intentions for a routine that feels like you.'],transfer:['Take your progress with you.','Your journal stays yours, wherever life takes you.'],scan:['From your plate to your journal.','A photo, a quick review, and one less thing to think about.']};
function render(){
  if(!session)return;
  page=location.hash.slice(1)||'overview';if(!titles[page])page='overview';
  document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===page);a.setAttribute('aria-current',a.dataset.page===page?'page':'false');});
  $('#page-label').textContent=({overview:'Overview',food:'Food journal',activity:'Activity',progress:'Progress',goals:'My goals',transfer:'Backup & transfer',scan:'Photo meal'})[page];
  $('#profile-name').textContent=state.name||(session.guest?'Guest':'Your space');const letter=(state.name||(session.guest?'Guest':'Y')).slice(0,1).toUpperCase();document.querySelectorAll('.avatar').forEach(e=>e.textContent=letter);
  const dateText=new Date(date+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
  $('#main').innerHTML=`<div class="heading"><div><div class="eyebrow">${state.name?'YOUR DAILY SPACE, '+esc(state.name):'YOUR DAILY SPACE'}</div><h1>${titles[page][0]}</h1><p>${titles[page][1]}</p></div><label class="date-control">${uiIcon('calendar',17)}<span>${dateText}</span><input aria-label="Journal date" type="date" id="date" value="${date}" max="${today()}"></label></div>${state.demo?'<div class="journal-date"><span class="demo-label">EXAMPLE JOURNAL</span> Sample meals and water are included to help you explore. <button class="text-button" data-action="clear">Start fresh</button></div>':''}${({overview,food,activity,progress,goals,transfer:transferPage,scan:scanPage})[page]()}`;
  if(session.guest)$('#main').insertAdjacentHTML('afterbegin','<div class="migration-banner guest-banner"><span><strong>Guest mode</strong> <span class="banner-detail">· Your progress is saved on this device.</span></span><a class="text-button" href="#transfer">Backup &amp; options ↗</a></div>');
  if(legacyAvailable())$('#main').insertAdjacentHTML('afterbegin','<div class="migration-banner"><span>Your original journal is still on this device.</span><button class="text-button" data-account="legacy">Review &amp; move journal ↗</button></div>');
  $('#date').onchange=e=>{if(e.target.value&&e.target.value<=today()){date=e.target.value;render();}};
  if(page==='scan')bindScan();else stopCamera();
}

const input=(label,name,type='number',value='',attrs='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs} required></label>`;
function openForm(kind){const f=$('#entry-form');let html='';if(kind==='meal'){html=`${input('Food or dish','name','text','','maxlength="90" placeholder="e.g. Dal, rice & vegetables"')}<label>Meal<select name="meal"><option>Breakfast</option><option>Lunch</option><option>Dinner</option><option>Snack</option></select></label>${input('Calories (kcal)','calories','number','','min="0" max="10000" step="1"')}<div class="form-row">${input('Protein (g)','protein','number',0,'min="0" max="1000" step="0.1"')}${input('Carbs (g)','carbs','number',0,'min="0" max="1000" step="0.1"')}</div>${input('Fat (g)','fat','number',0,'min="0" max="1000" step="0.1"')}<p class="form-help">Enter estimates from your food label or recipe. Logged for ${date}.</p>`;}else if(kind==='activity'){html=`<label>Activity<select name="type"><option>Walk</option><option>Run</option><option>Cycling</option><option>Yoga</option><option>Strength training</option><option>Swimming</option><option>Other</option></select></label>${input('Duration (minutes)','minutes','number','','min="1" max="1440" step="1"')}<label>Note (optional)<input name="note" maxlength="120" placeholder="e.g. A walk around the park"></label>`;}else if(kind==='weight'){html=`${input('Weight (kg)','weight','number',day().weight||'','min="1" max="700" step="0.1"')}<p class="form-help">Saved for ${date}. A new value replaces that day’s entry.</p>`;}else if(kind==='settings'){html=`<label>Your name (optional)<input name="name" value="${esc(state.name)}" maxlength="40" placeholder="What should we call you?"></label><p class="form-help">These targets are set by you. They are not calculated health advice.</p><div class="form-row">${input('Calories (kcal)','calories','number',state.goals.calories,'min="1" max="20000" step="1"')}${input('Water (ml)','water','number',state.goals.water,'min="1" max="20000" step="1"')}</div><div class="form-row">${input('Movement (min)','activity','number',state.goals.activity,'min="1" max="1440" step="1"')}${input('Protein (g)','protein','number',state.goals.protein,'min="1" max="1000" step="1"')}</div><div class="form-row">${input('Carbs (g)','carbs','number',state.goals.carbs,'min="1" max="2000" step="1"')}${input('Fat (g)','fat','number',state.goals.fat,'min="1" max="1000" step="1"')}</div>`;}else if(kind==='clear'){html='<p class="form-help">Clear all meals, water, activities and weight entries in this browser? Your name and goals will stay. Export first if you want to keep a copy.</p>';}$('#dialog-title').textContent=({meal:'What’s on your plate?',activity:'A little movement',weight:'Log your weight',settings:'Make Bloom yours',clear:'Start with a fresh journal?'})[kind];f.innerHTML=html+`<button class="primary" type="submit">${kind==='clear'?'Clear journal':'Save '+(kind==='settings'?'changes':'entry')}</button>`;f.onsubmit=async e=>{e.preventDefault();if(!session||busy)return;if(!f.reportValidity())return;const values=Object.fromEntries(new FormData(f));if(kind==='meal'){if(!values.name.trim()){f.elements.name.setCustomValidity('Enter a food or dish name.');f.elements.name.reportValidity();f.elements.name.oninput=()=>f.elements.name.setCustomValidity('');return;}writableDay().meals.push({id:crypto.randomUUID(),name:values.name.trim(),meal:values.meal,...Object.fromEntries(['calories','protein','carbs','fat'].map(k=>[k,Number(values[k])]))});}else if(kind==='activity'){writableDay().activities.push({id:crypto.randomUUID(),type:values.type,minutes:Number(values.minutes),note:values.note.trim()});}else if(kind==='weight'){writableDay().weight=Number(values.weight);}else if(kind==='settings'){state.name=values.name.trim();for(const k of Object.keys(state.goals))state.goals[k]=Number(values[k]);}else{state.days={};state.demo=false;}const saved=await save();$('#modal').close();render();if(saved)toast(kind==='clear'?'Your fresh journal is ready.':'Saved. A little progress, recorded.');};$('#modal').showModal();}
async function exportJournal(){await backupAccount();}
document.addEventListener('click',async e=>{if(!session||busy)return;const el=e.target.closest('[data-action],[data-remove-meal],[data-remove-activity],[data-remove-weight]');if(!el)return;if(el.dataset.removeMeal){writableDay().meals=day().meals.filter(m=>m.id!==el.dataset.removeMeal);await save();render();return;}if(el.dataset.removeActivity){writableDay().activities=day().activities.filter(a=>a.id!==el.dataset.removeActivity);await save();render();return;}if(el.dataset.removeWeight){state.days[el.dataset.removeWeight].weight=null;await save();render();return;}const action=el.dataset.action;if(action==='export')exportJournal();else if(action==='water-plus'||action==='water-minus'){writableDay().water=Math.min(100000,Math.max(0,day().water+(action==='water-plus'?250:-250)));await save();render();}else openForm(action);});
$('#close-modal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});$('#settings').onclick=$('#profile-button').onclick=()=>openForm('settings');$('#export').onclick=exportJournal;window.addEventListener('hashchange',render);
